const prev = $('Build AI System Prompt').item.json;
const allowed = prev.allowedActions;
const allowedActors = ['customer','driver','unknown'];
const allowedTrust = ['L0','L1','L2','L3'];
const text = String(prev.text || '').toLowerCase();
const rawText = String(prev.text || '').trim();
const session = prev.session || {};
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}
const lang = detectLang(rawText);

const extractOrder = (value) => {
  const s = String(value || '');
  const m =
    s.match(/X360[-_][A-Z0-9-]{6,}/i) ||
    s.match(/ORDER[-_][A-Z0-9-]{4,}/i) ||
    s.match(/\b[A-Z]{2,}\d[-A-Z0-9]{5,}\b/i) ||
    s.match(/\b[A-Z0-9]{3,}[-_][A-Z0-9-]{4,}\b/i);
  return m ? m[0].toUpperCase() : '';
};

const orderFromMsg = extractOrder(rawText);
const orderRef = orderFromMsg || prev.lastOrderReference || session.orderReference || '';

const isGreeting = /^(hi|hello|hey|salam|assalam|marhaba|good morning|good evening)\b/i.test(rawText);
const isHelpQuestion = /\b(what is|what's|whats|what does|where (can|do|to|should) (i |)(find|get)|where is my|how (do i|to) find|don't know|dont know|do not know|i don't have|i dont have|no order|not sure|explain|tell me (where|what)|tracking reference|tracking number|order id|order ref|order number|reference number|what.*mean)\b/i.test(text) || rawText === 'where?' || rawText === 'where';
const isHowToQuestion = /\b(how (to|do i)|want to know how|how does.*work|steps to|process for)\b/i.test(text) && /\b(deliver|delivery|collect|pickup|pick up|locker)\b/i.test(text);
const userConfused = isHelpQuestion || isHowToQuestion;
const mentionsCarrier = /\bnoon\b|\bamazon\b|\bama[sz]on\b|\bjahez\b|\bdriver\b|\bdelivery from\b|\brider\b/.test(text);
const wantsOperationalLocation = /\b(send (me )?loc|locker|google ?maps|my location|delivery location|where (is|should i deliver|to deliver))\b/i.test(text) || (/\b(address|map)\b/i.test(text) && !isHelpQuestion);
const wantsOtp = /\botp\b|\bcode\b|\bpin\b|\bopen (the )?locker\b/i.test(text);

const HELP_REPLIES = {
  en: {
    findRef: "The order/tracking number is usually in your delivery SMS, the courier app (Noon/Amazon etc.), or on the shipping label. Once you have it, send it here and I'll pull your locker details.",
    howDeliver: "Sure — if you're dropping off a package, share the order/tracking number from the label or app and I'll send you the locker location. Are you delivering or collecting?",
    greeting: "Hi! I'm from LLBox. Are you delivering a package or collecting one?",
    thanks: "You're welcome! Let me know if you need the locker location or OTP.",
  },
  ar: {
    findRef: "رقم الطلب/التتبع عادةً في رسالة SMS أو تطبيق التوصيل أو على ملصق الشحنة. أرسله هنا وسأجلب لك تفاصيل الصندوق.",
    howDeliver: "تمام — إذا كنت تسلّم طرداً، أرسل رقم الطلب/التتبع من الملصق أو التطبيق وسأرسل لك موقع الصندوق. هل أنت سائق أم مستلم؟",
    greeting: "مرحباً! أنا من LLBox. هل أنت سائق توصيل أم تستلم طرداً؟",
    thanks: "العفو! أخبرني إذا احتجت موقع الصندوق أو OTP.",
  },
  ur: {
    findRef: "آرڈر/ٹریکنگ نمبر عام طور پر SMS، کورئیر ایپ، یا پیکج لیبل پر ہوتا ہے۔ بھیج دیں، میں لاکر کی تفصیل نکال لوں گا۔",
    howDeliver: "اگر آپ ڈیلیور کر رہے ہیں تو لیبل یا ایپ سے آرڈر/ٹریکنگ نمبر بھیجیں، میں لاکر لوکیشن بھیج دوں گا۔ آپ ڈرائیور ہیں یا پیکج لینے آئے ہیں؟",
    greeting: "سلام! میں LLBox سے ہوں۔ آپ ڈیلیوری کر رہے ہیں یا پیکج collect کرنا ہے؟",
    thanks: "خوش آمدید! لاکر location یا OTP چاہیے تو بتائیں۔",
  },
};
const L = HELP_REPLIES[lang] || HELP_REPLIES.en;

let out = null;
try {
  out = JSON.parse($json.choices?.[0]?.message?.content || '{}');
} catch (e) { out = null; }

const safeFallback = {
  actor: prev.actorType || 'unknown',
  intent: 'CHAT',
  language: lang,
  trust_level: prev.trustLevel || 'L0',
  requires_verification: false,
  action: 'chat',
  tool_required: false,
  confidence: 0,
  reply: isGreeting ? L.greeting : (userConfused ? L.findRef : L.howDeliver),
};

let aiUsed = true;
if (!out || typeof out !== 'object') { out = { ...safeFallback }; aiUsed = false; }
if (!allowed.includes(out.action)) out.action = 'chat';
if (!allowedActors.includes(out.actor)) out.actor = prev.actorType || 'unknown';
if (!allowedTrust.includes(out.trust_level)) out.trust_level = prev.trustLevel || 'L0';
if (typeof out.tool_required !== 'boolean') out.tool_required = false;
if (typeof out.reply !== 'string' || !out.reply.trim()) out.reply = safeFallback.reply;
if (/i'?m here to help with llbox deliveries and lockers/i.test(out.reply)) out.reply = safeFallback.reply;

// Strip bullet-list style replies — WhatsApp should feel human
if (/^\s*[\d\-\*•]/m.test(out.reply) || (out.reply.match(/\n/g) || []).length > 1) {
  out.reply = userConfused ? L.findRef : safeFallback.reply;
}

// --- Priority overrides (most specific first) ---

if (isGreeting && !orderRef) {
  out.action = 'chat';
  out.tool_required = false;
  out.intent = 'GREETING';
  out.reply = L.greeting;
} else if (/^(thanks|thank you|shukriya|jazakallah|ok|okay|got it)\b/i.test(rawText)) {
  out.action = 'chat';
  out.tool_required = false;
  out.intent = 'ACK';
  out.reply = L.thanks;
} else if (userConfused && !orderRef) {
  out.action = 'chat';
  out.tool_required = false;
  out.intent = isHowToQuestion ? 'HOW_TO_HELP' : 'HELP_FIND_REFERENCE';
  out.reply = isHowToQuestion ? L.howDeliver : L.findRef;
} else if (mentionsCarrier && !orderRef && !userConfused) {
  out.actor = 'driver';
  out.action = 'chat';
  out.tool_required = false;
  out.intent = 'DRIVER_NEED_ORDER_REF';
  out.reply = "Got it — send me the order/tracking number from the label or app and I'll pull the locker location for you.";
} else if (orderRef && (wantsOperationalLocation || wantsOtp || (mentionsCarrier && !userConfused))) {
  out.actor = out.actor === 'customer' ? 'customer' : 'driver';
  out.action = wantsOtp && out.actor === 'customer' ? 'request_collection_otp' : 'resolve_delivery_access';
  out.tool_required = true;
  out.intent = 'RESOLVE_DELIVERY';
  if (!out.reply || /clarify|what assistance|how can i assist|please share your order/i.test(out.reply)) {
    out.reply = wantsOtp ? `Checking order ${orderRef} for your OTP now.` : `Got it — checking ${orderRef} now, one sec.`;
  }
}

// Never call tools for pure help/chat intents
if (['GREETING','HELP_FIND_REFERENCE','HOW_TO_HELP','ACK','CHAT'].includes(out.intent)) {
  out.action = 'chat';
  out.tool_required = false;
}

out.trust_level = prev.trustLevel || out.trust_level;
out.order_reference = orderRef || out.order_reference || '';

if (orderRef) {
  const s = staticData.sessions[prev.phone] || session || {};
  s.orderReference = orderRef;
  s.currentSubState = 'HAS_ORDER_REF';
  s.lastActivity = Date.now();
  staticData.sessions[prev.phone] = s;
}

return [{ json: {
  ...prev,
  aiDecision: out,
  aiUsed,
  userConfused,
  isHelpQuestion,
  lastOrderReference: orderRef || prev.lastOrderReference || '',
  session: { ...(session || {}), orderReference: orderRef || session.orderReference || '' }
} }];

const j = $json;
const d = j.aiDecision;
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const session = staticData.sessions[j.phone] || {};
const orderReference = j.lastOrderReference || session.orderReference || d.order_reference || '';

const MIN_TRUST = {
  none: 'L0', chat: 'L0', ask_name: 'L0', save_name: 'L0',
  get_customer_profile: 'L2', get_delivery_status: 'L1', get_delivery_details: 'L1',
  get_customer_locker: 'L1', get_locker_location: 'L1', get_locker_availability: 'L1',
  register_delivery: 'L0', start_collection: 'L1', get_collection_status: 'L1',
  request_collection_otp: 'L0',
  create_support_ticket: 'L0', create_complaint: 'L1', create_privacy_request: 'L1',
  request_account_recovery: 'L1',
  verify_driver: 'L1', verify_delivery: 'L1', get_assigned_delivery: 'L1',
  get_assigned_locker: 'L1', verify_agent_location: 'L1', request_delivery_access: 'L0',
  resolve_delivery_access: 'L0', check_otp_status: 'L1', record_delivery_failure: 'L1',
  request_second_attempt: 'L1', create_driver_support_case: 'L1',
  create_security_incident: 'L0', create_operations_incident: 'L1',
  human_escalation: 'L0'
};
const RANK = { L0: 0, L1: 1, L2: 2, L3: 3, L4: 4, L5: 5 };
const ESCALATE_ONLY = new Set(['request_account_recovery', 'create_security_incident']);
const ORDER_REF_ACTIONS = new Set([
  'resolve_delivery_access','request_delivery_access','request_collection_otp',
  'register_delivery','get_delivery_status','get_delivery_details','get_locker_location'
]);

const action = d.action;
const requiredTrust = MIN_TRUST[action];
let allowed = false;
let denyReason = null;

if (requiredTrust === undefined) {
  denyReason = 'ACTION_NOT_ALLOWLISTED';
} else if (ESCALATE_ONLY.has(action)) {
  denyReason = 'REQUIRES_HUMAN_STEP_UP';
} else if (ORDER_REF_ACTIONS.has(action) && !orderReference && action !== 'register_delivery') {
  denyReason = 'MISSING_ORDER_REFERENCE';
} else if (RANK[j.trustLevel || 'L0'] < RANK[requiredTrust]) {
  // Order-reference actions are allowed at L0 when we have an order ID.
  if (ORDER_REF_ACTIONS.has(action) && orderReference) {
    allowed = true;
  } else {
    denyReason = 'INSUFFICIENT_TRUST_LEVEL';
  }
} else {
  allowed = true;
}

if (allowed && (action === 'request_collection_otp' || action === 'resolve_delivery_access')) {
  const attempts = session.otpAttempts || 0;
  const cfg = $('Config').item.json;
  const limit = parseInt(cfg.rateLimitOtpPerHour || '8', 10);
  if (attempts >= limit) {
    allowed = false;
    denyReason = 'OTP_TOO_MANY_ATTEMPTS';
  } else {
    session.otpAttempts = attempts + 1;
    if (orderReference) session.orderReference = orderReference;
    staticData.sessions[j.phone] = session;
  }
}

const idempotencyKey = `${j.correlationId}:${j.messageId}:${action}`;

return [{ json: {
  ...j,
  lastOrderReference: orderReference,
  gate: {
    allowed,
    denyReason,
    action,
    requiredTrust: requiredTrust || 'L4',
    idempotencyKey
  }
} }];

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}

const j = $json;
const reason = j.gate.denyReason;
const name = j.knownName || '';
const lang = detectLang(j.text || '');
const greet = name ? (lang === 'en' ? `${name}, ` : `${name}، `) : '';

const MESSAGES = {
  MISSING_ORDER_REFERENCE: {
    en: `${greet}Sure — please send the order ID / reference and I’ll pull the delivery details for you.`,
    ar: `${greet}تمام — أرسل رقم الطلب / المرجع وسأجلب تفاصيل التوصيل مباشرة.`,
    ur: `${greet}بالکل — آرڈر آئی ڈی / ریفرنس بھیج دیں، میں ڈیلیوری تفصیل نکال لیتا ہوں۔`
  },
  INSUFFICIENT_TRUST_LEVEL: {
    en: `${greet}I just need the order ID/reference first so I can help safely.`,
    ar: `${greet}أحتاج رقم الطلب أولاً حتى أقدر أساعدك بشكل صحيح.`,
    ur: `${greet}محفوظ مدد کے لیے پہلے آرڈر آئی ڈی/ریفرنس بھیج دیں۔`
  },
  NO_CUSTOMER_OWNERSHIP_CONTEXT: {
    en: `${greet}Can you share the order reference linked to this delivery?`,
    ar: `${greet}هل يمكنك مشاركة رقم الطلب المرتبط بهذه الشحنة؟`,
    ur: `${greet}اس ڈیلیوری کا آرڈر ریفرنس شیئر کر سکتے ہیں؟`
